begin;
create extension if not exists pgtap with schema extensions;set local search_path=public,extensions;select plan(16);
insert into auth.users(id,email,raw_app_meta_data,raw_user_meta_data)values('18000000-0000-4000-8000-000000000001','mileage-owner@example.test','{}','{}'),('18000000-0000-4000-8000-000000000002','mileage-outsider@example.test','{}','{}');
insert into public.workspaces(id,name,owner_id)values('28000000-0000-4000-8000-000000000001','Mileage Workspace','18000000-0000-4000-8000-000000000001'),('28000000-0000-4000-8000-000000000002','Other Mileage Workspace','18000000-0000-4000-8000-000000000002');
set local role authenticated;select throws_ok($$select public.mutate_mileage_record('28000000-0000-4000-8000-000000000001','18000000-0000-4000-8000-000000000001','mileage-denied','vehicle','create',null,null,'hash','{}')$$,'42501',null,'authenticated clients cannot call the service-role function');reset role;
create temporary table vehicle_create as select public.mutate_mileage_record('28000000-0000-4000-8000-000000000001','18000000-0000-4000-8000-000000000001','mileage-vehicle-create','vehicle','create',null,null,'vehicle-hash','{"name":"Primary SUV","make":"Volvo","model":"XC60","year":2024,"odometerYear":2026,"beginningOdometer":"10000.00","endingOdometer":"12000.00","isPrimary":true,"deviceId":"database-test"}') result;
select is((select result->>'version' from vehicle_create),'1','vehicle starts at version one');select is((select odometer_year from public.vehicles where id=(select(result->>'id')::uuid from vehicle_create)),2026,'annual odometer year is stored');select ok((select is_primary from public.vehicles where id=(select(result->>'id')::uuid from vehicle_create)),'primary vehicle is stored');select is((select count(*)::integer from public.sync_operations where client_mutation_id='mileage-vehicle-create'),1,'vehicle create writes a sync receipt');select is((select count(*)::integer from public.audit_events where request_id='mileage-vehicle-create'),1,'vehicle create writes an audit event');
select is(public.mutate_mileage_record('28000000-0000-4000-8000-000000000001','18000000-0000-4000-8000-000000000001','mileage-vehicle-create','vehicle','create',null,null,'vehicle-hash','{}')->>'id',(select result->>'id' from vehicle_create),'duplicate retry returns original vehicle');
create temporary table trip_create as select public.mutate_mileage_record('28000000-0000-4000-8000-000000000001','18000000-0000-4000-8000-000000000001','mileage-trip-create','mileage_trip','create',null,null,'trip-hash',jsonb_build_object('vehicleId',(select result->>'id' from vehicle_create),'tripDate','2026-08-19','purpose','Listing appointment','startLocation','Office','endLocation','Property','startOdometer','10100.00','endOdometer','10112.50','miles','12.50','mileageRate','0.7250','mileageRateYear',2026,'rateSource','default','parking','4.25','tolls','2.00','deviceId','database-test'))result;
select is((select mileage_rate::text from public.mileage_trips where id=(select(result->>'id')::uuid from trip_create)),'0.7250','2026 rate is stored exactly');select is((select deduction_amount::text from public.mileage_trips where id=(select(result->>'id')::uuid from trip_create)),'15.31','mileage plus parking and tolls is calculated exactly');select is((select count(*)::integer from public.sync_operations where client_mutation_id='mileage-trip-create'),1,'trip create writes a sync receipt');select is((select count(*)::integer from public.audit_events where request_id='mileage-trip-create'),1,'trip create writes an audit event');
select throws_ok(format($$select public.mutate_mileage_record('28000000-0000-4000-8000-000000000001','18000000-0000-4000-8000-000000000001','mileage-trip-stale','mileage_trip','update',%L,2,'stale',jsonb_build_object('vehicleId',%L,'tripDate','2026-08-19','purpose','Stale edit','miles','12.50','mileageRate','0.7250','mileageRateYear',2026,'rateSource','default','parking','0.00','tolls','0.00'))$$,(select result->>'id' from trip_create),(select result->>'id' from vehicle_create)),'40001','Record version conflict','stale trip update is rejected');
select throws_ok(format($$select public.mutate_mileage_record('28000000-0000-4000-8000-000000000001','18000000-0000-4000-8000-000000000001','mileage-vehicle-blocked','vehicle','void',%L,1,'blocked','{"reason":"Vehicle retired"}')$$,(select result->>'id' from vehicle_create)),'P0001','Void the vehicle trips before removing this vehicle','vehicle with trips cannot be voided');
select public.mutate_mileage_record('28000000-0000-4000-8000-000000000001','18000000-0000-4000-8000-000000000001','mileage-trip-void','mileage_trip','void',(select(result->>'id')::uuid from trip_create),1,'void-hash','{"reason":"Duplicate trip","deviceId":"database-test"}');select ok((select deleted_at is not null and void_reason='Duplicate trip' from public.mileage_trips where id=(select(result->>'id')::uuid from trip_create)),'trip void is non-destructive and retains its reason');
select public.mutate_mileage_record('28000000-0000-4000-8000-000000000001','18000000-0000-4000-8000-000000000001','mileage-vehicle-void','vehicle','void',(select(result->>'id')::uuid from vehicle_create),1,'vehicle-void-hash','{"reason":"Vehicle retired","deviceId":"database-test"}');select ok((select deleted_at is not null and void_reason='Vehicle retired' from public.vehicles where id=(select(result->>'id')::uuid from vehicle_create)),'vehicle void is non-destructive after trips are voided');
select throws_ok($$select public.mutate_mileage_record('28000000-0000-4000-8000-000000000001','18000000-0000-4000-8000-000000000002','mileage-unauthorized','vehicle','create',null,null,'x','{"name":"No access","odometerYear":2026}')$$,'P0001','Not authorized to change mileage records','service function rechecks actor membership');
select * from finish();rollback;
